from html.parser import HTMLParser
from urllib.request import urlopen
from urllib.parse import urljoin
import re

class Crawler(HTMLParser):

    def __init__(self, url):
        super().__init__()
        self.url = url
        self.links = set()

    def handle_starttag(self, tag, attrs):
        if tag == 'a':
            for attr in attrs:
                if attr[0] == 'href':
                    link = attr[1]
                    if re.match(r'^https?://', link):
                        self.links.add(link)

    def crawl(self):
        html = urlopen(self.url).read().decode()
        self.feed(html)
        for link in self.links:
            if 'example.com' in link:
                self.crawl(link)

crawler = Crawler('http://test.com')
crawler.crawl()

